const nextRandom = (seed: number) => { const n = (seed * 1664525 + 1013904223) >>> 0; return [n / 4294967296, n] as const; };
const key = (p: Point) => `${p.x},${p.y}`;
const tapPath = (map: Tile[][], seen: boolean[][], start: Point, goal: Point) => {
  if (map[goal.y]?.[goal.x] === "#") return [] as Point[];
  const queue = [start], previous = new Map<string, Point | null>([[key(start), null]]);
  for (let index = 0; index < queue.length; index++) {
    const current = queue[index];
    if (current.x === goal.x && current.y === goal.y) break;
    for (const delta of [{x:0,y:-1},{x:-1,y:0},{x:0,y:1},{x:1,y:0}]) {
      const next = {x:current.x+delta.x,y:current.y+delta.y}, id = key(next);
      if (previous.has(id) || map[next.y]?.[next.x] === "#" || !seen[next.y]?.[next.x]) continue;
      previous.set(id,current); queue.push(next);
    }
  }
  if (!previous.has(key(goal))) return [] as Point[];
  const path: Point[] = []; let current: Point | null = goal;
  while (current) { path.unshift(current); current = previous.get(key(current)) ?? null; }
  return path;
};

