const displayGearDelta=(locale:Locale,item:Gear,current:OwnedGear|null|undefined)=>{if(locale==="ja")return gearDelta(item,current);const parts=([["atk","ATK"],["def","DEF"],["hp","HP"],["mp","MP"]] as const).flatMap(([key,label])=>{const delta=(item[key]??0)-(current?.[key]??0);return delta?[`${label} ${delta>0?"+":""}${delta}`]:[];});if(item.passive!==current?.passive)parts.push(item.passive?`Switch to ${passiveLabel(locale,item.passive)}`:"No passive");return parts.join(" / ")||"Same stats";};
