function GemGauge({ kind, value, max }: { kind: "hp" | "mp"; value: number; max: number }) {
  const ratio=Math.max(0,Math.min(1,value/Math.max(1,max)));
  return <div className={`gem-gauge gem-${kind}`} role="meter" aria-label={`${kind.toUpperCase()} ${value}/${max}`} aria-valuemin={0} aria-valuemax={max} aria-valuenow={value}><span className="gem-caption"><i aria-hidden="true"/><b>{kind.toUpperCase()}</b><em>{value}/{max}</em></span><span className="gem-track" aria-hidden="true">{Array.from({length:10},(_,index)=>{const fill=Math.max(0,Math.min(1,ratio*10-index));return <i className={fill>0?"lit":""} key={index}><em style={{width:`${fill*100}%`}}/></i>;})}</span></div>;
}

function StatusBadges({ statuses, locale }: { statuses: Status[]; locale: Locale }) {
  if(!statuses.length)return null;
  return <div className="status-badges" aria-label={pick(locale,"状態異常","Status ailments")}>{statuses.map(status=>{const info=statusCopy(locale,status.kind);return <span className={`status-badge status-${status.kind}`} key={status.kind} aria-label={`${info.name}, ${status.turns} turns. ${info.effect}. ${info.cure}`}><b>{info.name}</b><em>{status.turns}T</em><small>{info.effect} · {info.cure}</small></span>;})}</div>;
}

