function RunResultCard({ result, meta, locale, onRetry, onOpenRanking, compact = false }: { result: Result; meta: Meta; locale: Locale; onRetry: () => void; onOpenRanking?: () => void; compact?: boolean }) {
  const death=result.death;
  const enemy=death?localizedBattleName(locale,monsterRecordFor(death.enemyCatalogId),death.enemyFloor,death.boss,death.graveEater):"";
  const grave=meta.grave;
  return <section className={`run-result ${result.reason} ${compact?"compact":""}`} aria-live="polite">
    <span>{resultLabel(locale,result.reason)}</span>
    <h2>{pick(locale,"地下","Floor")} {result.floor}</h2>
    <p>{pick(locale,`得点 ${result.score.toLocaleString()} ／ 討伐 ${result.kills} ／ 階層主 ${result.bosses}`,`Score ${result.score.toLocaleString()} / Kills ${result.kills} / Bosses ${result.bosses}`)}</p>
    {result.route==="descent"&&<small className="ranking-note">{pick(locale,"奈落降下ルートの記録は総合ランキングに登録されません。","Abyss Descent route runs are excluded from the global ranking.")}</small>}
    {death&&<div className="death-review"><b>{pick(locale,"死因","Cause")}: {deathCauseLabel(locale,death.cause)}</b><small>{enemy}の{intentCopy(locale,death.intent).label}で倒れた。</small><p>{deathAdvice(locale,death.cause)}</p></div>}
    <div className={`result-quest ${result.questComplete?"complete":""}`}><b>{pick(locale,"地下依頼","Request")}</b><span>{questText(locale,result.quest)} · {result.questProgress}/{result.questTarget}{result.questComplete?pick(locale,"　達成","  Complete"):""}</span></div>
    <div className="result-meta"><span>{pick(locale,"熟練度","Mastery")} {result.mastery}（+{result.masteryGain}）</span><span>{result.nextMastery?`${pick(locale,"次の称号","Next title")}: ${nextMasteryTitle(locale,result.nextMastery)} / ${result.nextMastery-result.mastery}`:nextMasteryTitle(locale,null)}</span></div>
    {result.reason==="dead"&&result.graveItems>0&&grave&&<div className="result-grave"><b>{pick(locale,`墓：地下${grave.floor}階・${result.graveItems}件`,`Grave: Floor ${grave.floor} · ${result.graveItems} items`)}</b><small>{pick(locale,"回収候補：","Recovery candidates: ")}{grave.items.slice(0,3).map(item=>displayGearName(locale,item)).join(" / ")}{grave.items.length>3?` +${grave.items.length-3}`:""}</small></div>}
    {!compact&&<div className="run-result-actions"><button className="primary" onClick={onRetry}>{pick(locale,"もう一度潜る","Descend Again")}</button>{onOpenRanking&&<button onClick={onOpenRanking}>{pick(locale,"ランキングを見る","View Ranking")}</button>}</div>}
    {compact&&<button className="primary" onClick={onRetry}>{pick(locale,"もう一度潜る","Descend Again")}</button>}
  </section>;
}

class GameErrorBoundary extends Component<{children:ReactNode},{failed:boolean}> {
  state={failed:false};
  static getDerivedStateFromError(){return{failed:true};}
  componentDidCatch(error:unknown){try{sessionStorage.setItem("chika-hyakkei-last-render-error",error instanceof Error?error.message:String(error));}catch{}}
  restoreBackup=()=>{const backup=localStorage.getItem(RUN_BACKUP_KEY);if(backup)localStorage.setItem(RUN_KEY,backup);window.location.reload();};
  restoreMeta=()=>{const backup=localStorage.getItem(META_BACKUP_KEY);if(!backup)return;try{if(!normalizeMeta(JSON.parse(backup)))return;const current=localStorage.getItem(META_KEY);if(current)localStorage.setItem(META_QUARANTINE_KEY,current);localStorage.setItem(META_KEY,backup);window.location.reload();}catch{window.alert("記録を復元できませんでした。保存領域を確認してください。");}};
  returnToTitle=()=>{const current=localStorage.getItem(RUN_KEY);if(current)localStorage.setItem(RUN_QUARANTINE_KEY,current);localStorage.removeItem(RUN_KEY);window.location.reload();};
  render(){if(!this.state.failed)return this.props.children;const hasBackup=typeof window!=="undefined"&&Boolean(localStorage.getItem(RUN_BACKUP_KEY));return <main className="recovery-screen"><section><span>RECOVERY MODE</span><h1>表示を復旧できます</h1><p>画面の処理中にエラーが起きました。冒険データは消去せず、復旧用に残しています。</p>{hasBackup&&<button className="primary" onClick={this.restoreBackup}>ひとつ前のセーブで再開</button>}<button onClick={this.restoreMeta}>図鑑・最高記録をバックアップから復元</button><button onClick={()=>window.location.reload()}>そのまま再読み込み</button><button onClick={this.returnToTitle}>現在の冒険を退避してタイトルへ</button><small>退避したデータは自動削除しません。</small></section></main>;}
}

